function styleDisplayName(value:string,style:string){
 if(style==='normal')return value
 const ranges:Record<string,[number,number]>={bold:[0x1d400,0x1d41a],italic:[0x1d434,0x1d44e],'bold-italic':[0x1d468,0x1d482],script:[0x1d49c,0x1d4b6],fraktur:[0x1d504,0x1d51e],'double-struck':[0x1d538,0x1d552],monospace:[0x1d670,0x1d68a],'sans-bold':[0x1d5d4,0x1d5ee]}
 const range=ranges[style];if(!range)return value
 const digitStarts:Record<string,number>={bold:0x1d7ce,'double-struck':0x1d7d8,monospace:0x1d7f6,'sans-bold':0x1d7ec}
 const special:Record<string,Record<string,string>>={
  script:{B:'ℬ',E:'ℰ',F:'ℱ',H:'ℋ',I:'ℐ',L:'ℒ',M:'ℳ',R:'ℛ',e:'ℯ',g:'ℊ',o:'ℴ',h:'ℎ'},
  fraktur:{C:'ℭ',H:'ℌ',I:'ℑ',R:'ℜ',Z:'ℨ'},
  'double-struck':{C:'ℂ',H:'ℍ',N:'ℕ',P:'ℙ',Q:'ℚ',R:'ℝ',Z:'ℤ'}
 }
 return Array.from(value,ch=>{const cp=ch.codePointAt(0)!;if(special[style]?.[ch])return special[style][ch];if(cp>=65&&cp<=90)return String.fromCodePoint(range[0]+cp-65);if(cp>=97&&cp<=122)return String.fromCodePoint(range[1]+cp-97);if(cp>=48&&cp<=57&&digitStarts[style])return String.fromCodePoint(digitStarts[style]+cp-48);return ch}).join('')
}

function AvatarFrame({src,className=""}:{src:string;className?:string}){
 const [hovered,setHovered]=useState(false),[hoverCycle,setHoverCycle]=useState(0),[animatedReady,setAnimatedReady]=useState(false)
 const canvasRef=useRef<HTMLCanvasElement>(null),animationRef=useRef<HTMLImageElement>(null),timerRef=useRef<number|undefined>(undefined)
 const drawStill=(image:HTMLImageElement)=>{const canvas=canvasRef.current;if(!canvas)return;canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;canvas.getContext('2d')?.drawImage(image,0,0)}
 useEffect(()=>{const image=new Image();image.onload=()=>drawStill(image);image.src=src;return()=>{image.onload=null;if(timerRef.current)window.clearTimeout(timerRef.current)}},[src])
 const getAnimationDuration=async()=>{
  try{const response=await fetch(src);const bytes=new Uint8Array(await response.arrayBuffer());let offset=8,total=0,frames=0
   while(offset+12<=bytes.length){const length=(bytes[offset]<<24)|(bytes[offset+1]<<16)|(bytes[offset+2]<<8)|bytes[offset+3];const type=String.fromCharCode(...bytes.slice(offset+4,offset+8));if(type==="fcTL"&&length>=26){const numerator=(bytes[offset+28]<<8)|bytes[offset+29],denominator=(bytes[offset+30]<<8)|bytes[offset+31]||100;total+=(numerator/denominator)*1000;frames++}if(type==="IEND")break;offset+=12+length}
   return frames>1&&total>0?total:1200
  }catch{return 1200}
 }
 const startAnimation=()=>{if(timerRef.current)window.clearTimeout(timerRef.current);setAnimatedReady(false);setHoverCycle(v=>v+1);setHovered(true)}
 const finishAnimation=()=>{const image=animationRef.current;if(image&&image.complete)drawStill(image);setHovered(false);setAnimatedReady(false)}
 useEffect(()=>{if(!hovered||!animatedReady)return;let cancelled=false;void getAnimationDuration().then(duration=>{if(!cancelled)timerRef.current=window.setTimeout(finishAnimation,duration)});return()=>{cancelled=true;if(timerRef.current)window.clearTimeout(timerRef.current)}},[hovered,animatedReady,hoverCycle])
 return <span className={"avatar-frame-motion "+(hovered?"is-hovered ":"")+className} onMouseEnter={startAnimation} onMouseLeave={()=>{if(timerRef.current)window.clearTimeout(timerRef.current);if(hovered)finishAnimation()}} aria-hidden="true"><canvas ref={canvasRef}/>{hovered&&<img ref={animationRef} key={hoverCycle} className={animatedReady?"is-ready":""} src={src} onLoad={()=>setAnimatedReady(true)} alt="" draggable={false}/>}</span>
}

function PageTransition({pageKey,children}:{pageKey:string;children:ReactNode}){
 const [transition,setTransition]=useState({key:pageKey,phase:'idle' as 'idle'|'out'|'in'})
 const previous=useRef<ReactNode>(children)
 useEffect(()=>{if(pageKey===transition.key)return;setTransition({key:transition.key,phase:'out'});const timer=window.setTimeout(()=>setTransition({key:pageKey,phase:'in'}),150);return()=>window.clearTimeout(timer)},[pageKey,transition.key])
 useEffect(()=>{if(pageKey===transition.key&&transition.phase!=='out')previous.current=children},[children,pageKey,transition.key,transition.phase])
 useEffect(()=>{if(transition.phase!=='in')return;const timer=window.setTimeout(()=>setTransition(v=>({...v,phase:'idle'})),240);return()=>window.clearTimeout(timer)},[transition.key,transition.phase])
 const leaving=pageKey!==transition.key||transition.phase==='out'
 return <div className={'page-transition '+(leaving?'is-leaving':transition.phase==='in'?'is-entering':'')}>{leaving?previous.current:children}</div>
}

