const attachmentDB=()=>new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open('memento-attachments',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})
const storeAttachment=async(id:string,file:File)=>{const db=await attachmentDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
const readAttachment=async(id:string)=>{const db=await attachmentDB();return new Promise<Blob|null>((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)})}
const deleteAttachment=async(id:string)=>{const db=await attachmentDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
