 useEffect(()=>{if(active){setTitle(active.title);setBody(active.body);setEntryDate(active.date);setEntryTags(active.tags);setAttachments(active.attachments||[]);setEntryFolder(active.folderId||'');setSaved(true);setIsEditing(!!active.draft);setAttachmentUrls({});if(editor.current)editor.current.innerHTML=active.body}},[activeId])
 useEffect(()=>{if(!active?.draft)return;setEntries(all=>all.map(e=>e.id===active.id?{...e,title:title.trim(),date:entryDate||e.date,body,tags:entryTags,attachments,folderId:entryFolder||undefined}:e))},[activeId,title,body,entryDate,entryTags,attachments,entryFolder])
 useEffect(()=>{let live=true;const load=async()=>{const urls:Record<string,string>={};for(const item of attachments){const blob=await readAttachment(item.id);if(blob)urls[item.id]=URL.createObjectURL(blob)}if(live)setAttachmentUrls(urls);else Object.values(urls).forEach(URL.revokeObjectURL)};load();return()=>{live=false;Object.values(attachmentUrls).forEach(URL.revokeObjectURL)}},[activeId,attachments])
 const filters=useMemo(()=>parseQuery(query),[query])
