 const save=()=>{if(!active)return;setEntries(all=>all.map(e=>e.id===active.id?{...e,title:title.trim(),date:entryDate,body,tags:entryTags,attachments,folderId:entryFolder||undefined,draft:false,createdAt:e.createdAt||Date.now()}:e));setSaved(true);setIsEditing(false)}
 const create=(date=localToday())=>{const e:Entry={id:Date.now(),title:'',date,body:'',tags:[],attachments:[],createdAt:Date.now(),draft:true};setEntries(a=>[e,...a]);setActiveId(e.id);setSection('Journal');setMemo(false);setTitle('');setBody('');setEntryDate(date);setEntryTags([]);setAttachments([]);setEntryFolder(activeFolder);setSaved(false);setIsEditing(true)}
