 const addAttachments=async(files:FileList|null)=>{if(!files||!active)return;const added:Attachment[]=[];for(const file of Array.from(files)){const id=active.id+'-'+Date.now()+'-'+Math.random().toString(36).slice(2);await storeAttachment(id,file);added.push({id,name:file.name,type:file.type,size:file.size})}setAttachments(a=>[...a,...added]);setSaved(false)}
