 useEffect(()=>{const node=profileFeedSentinel.current;if(!node||visibleProfileEntries.length>=profileFeedEntries.length)return;const observer=new IntersectionObserver(items=>{if(items.some(item=>item.isIntersecting))setProfileVisibleCount(count=>Math.min(count+30,profileFeedEntries.length))},{rootMargin:'300px'});observer.observe(node);return()=>observer.disconnect()},[profileFeedEntries.length,visibleProfileEntries.length])
 const twitterRelative=(e:Entry)=>{const d=new Date(e.date+'T12:00:00');const options:Intl.DateTimeFormatOptions={month:'short',day:'numeric'};if(d.getFullYear()!==new Date().getFullYear())options.year='numeric';return d.toLocaleDateString('en',options)}
 const youtubeRelative=(e:Entry)=>{const stamp=e.createdAt||new Date(e.date+'T12:00:00').getTime();const seconds=Math.max(0,Math.floor((Date.now()-stamp)/1000));if(seconds<60)return `${seconds}s ago`;const mins=Math.floor(seconds/60);if(mins<60)return `${mins}m ago`;const hours=Math.floor(mins/60);if(hours<24)return `${hours}h ago`;const days=Math.floor(hours/24);if(days<7)return `${days}d ago`;const weeks=Math.floor(days/7);if(weeks<5)return `${weeks}w ago`;const months=Math.floor(days/30);if(months<12)return `${Math.max(1,months)}mo ago`;return `${Math.floor(days/365)}y ago`}
 const timeLabel=(e:Entry)=>{const d=e.createdAt?new Date(e.createdAt):new Date(e.date+'T12:00:00');return d.toLocaleTimeString('en',{hour:'numeric',minute:'2-digit',hour12:timeFormat!=='24'})}
 const exportEntries=()=>{let chosen=entries.slice();if(exportPeriod==='year')chosen=chosen.filter(e=>e.date.startsWith(exportYear));if(exportPeriod==='month')chosen=chosen.filter(e=>e.date.startsWith(exportMonth));if(exportPeriod==='day')chosen=chosen.filter(e=>e.date===exportDay);if(exportPeriod==='range')chosen=chosen.filter(e=>e.date>=exportStart&&e.date<=exportEnd);if(exportPeriod==='week'){const d=new Date(exportWeek+'T12:00:00');const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);const start=iso(d.getFullYear(),d.getMonth(),d.getDate());d.setDate(d.getDate()+6);const end=iso(d.getFullYear(),d.getMonth(),d.getDate());chosen=chosen.filter(e=>e.date>=start&&e.date<=end)}const payload=exportFormat==='json'?JSON.stringify(chosen,null,2):[['id','title','date','body','tags','folder','attachments'],...chosen.map(e=>[e.id,e.title,e.date,plain(e.body),e.tags.join('; '),e.folderId||'',(e.attachments||[]).map(a=>a.name).join('; ')])].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\\n');const blob=new Blob([payload],{type:exportFormat==='json'?'application/json':'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='memento-export.'+(exportFormat==='json'?'json':'csv');link.click();URL.revokeObjectURL(url)}
 const importCSV=async(file:File)=>{try{const rows=parseCSV(await file.text());if(rows.length<2)throw new Error('The CSV does not contain any entry rows.');const headers=rows[0].map(h=>h.trim().toLowerCase().replace(/[^a-z0-9]/g,''));const col=(...names:string[])=>headers.findIndex(h=>names.includes(h));const titleCol=col('title','name'),dateCol=col('date','created','timestamp'),createdAtCol=col('createdat'),bodyCol=col('data','body','content','text','entry','description'),tagsCol=col('tags','tag'),folderCol=col('folder','foldername');if(titleCol<0||dateCol<0||bodyCol<0)throw new Error('CSV needs data, date and title columns.');const batch='csv-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);const imported:Entry[]=rows.slice(1).map((r,i)=>{const parsedDate=parseImportedTimestamp(r[dateCol]||'');const date=parsedDate?iso(parsedDate.getFullYear(),parsedDate.getMonth(),parsedDate.getDate()):localToday();const rawCreatedAt=createdAtCol>=0?(r[createdAtCol]||'').trim():'';const numericCreatedAt=rawCreatedAt&&Number.isFinite(Number(rawCreatedAt))?Number(rawCreatedAt)*(Number(rawCreatedAt)<100000000000?1000:1):NaN;const parsedCreatedAt=Number.isFinite(numericCreatedAt)?numericCreatedAt:parseImportedTimestamp(rawCreatedAt)?.getTime();const createdAt=parsedCreatedAt??parsedDate?.getTime()??new Date(date+'T12:00:00').getTime();const rawTags=tagsCol>=0?(r[tagsCol]||''):'';const tags=rawTags.split(/[;|]/).map(t=>t.trim().toLowerCase()).filter(Boolean);return {id:Date.now()+i,title:(r[titleCol]||'').trim(),date,body:'<p>'+csvEscape((r[bodyCol]||'').trim())+'</p>',tags,folderId:folderCol>=0?(r[folderCol]||'').trim()||undefined:undefined,attachments:[],createdAt,importedBatch:batch}}).filter(e=>e.title.trim()||plain(e.body).trim());if(!imported.length)throw new Error('No valid entries were found in that CSV.');setEntries(all=>[...imported,...all]);setTags(all=>Array.from(new Set([...all,...imported.flatMap(e=>e.tags)])));setImportedFileName(file.name);setImportHistory(all=>[{id:batch,fileName:file.name,importedAt:Date.now(),count:imported.length},...all]);window.alert('Imported '+imported.length+' entries from '+file.name+'.')}catch(err){window.alert(err instanceof Error?err.message:'Could not import this CSV.')}}
  const removeImportedCSV=(batch:string)=>{const count=entries.filter(e=>e.importedBatch===batch).length;const record=importHistory.find(item=>item.id===batch);if(!count){setImportHistory(all=>all.filter(item=>item.id!==batch));return}if(!window.confirm('Remove '+count+' entries imported from '+(record?.fileName||'this CSV')+'? This cannot be undone.'))return;setEntries(all=>all.filter(e=>e.importedBatch!==batch));setImportHistory(all=>all.filter(item=>item.id!==batch));if(active?.importedBatch===batch)setActiveId(0)}
